import{_ as e,o,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"動作選單與即時預覽","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/actions-and-preview.md","filePath":"zh-HK/user-guide/actions-and-preview.md","lastUpdated":1787586465000}'),a={name:"zh-HK/user-guide/actions-and-preview.md"};function n(i,t,d,s,g,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="動作選單與即時預覽" tabindex="-1">動作選單與即時預覽 <a class="header-anchor" href="#動作選單與即時預覽" aria-label="Permalink to &quot;動作選單與即時預覽&quot;">​</a></h1><p>Lertaro 不僅能極速定位檔案，更集成了完善的快顯操作體系與強大的即時預覽面板，讓你無需頻繁開啟檔案總管即可完成檔案的檢視、管理與分發。</p><h2 id="_1-動作選單詳解" tabindex="-1">1. 動作選單詳解 <a class="header-anchor" href="#_1-動作選單詳解" aria-label="Permalink to &quot;1. 動作選單詳解&quot;">​</a></h2><p>在任意搜尋結果（檔案、資料夾、應用程式或外掛模組項目）上按下 <code>Ctrl+O</code> 或按方向鍵 <code>→</code>，即可展開該項目的快顯動作選單。</p><h3 id="內建核心動作速查" tabindex="-1">內建核心動作速查 <a class="header-anchor" href="#內建核心動作速查" aria-label="Permalink to &quot;內建核心動作速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">動作名稱</th><th style="text-align:left;">預設快捷鍵</th><th style="text-align:left;">功能說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>開啟</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">使用系統預設關聯程式開啟選取的檔案或啟動應用程式。</td></tr><tr><td style="text-align:left;"><strong>在檔案總管中定位</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">開啟檔案所在目錄，並在檔案總管中直接選取該檔案。</td></tr><tr><td style="text-align:left;"><strong>以系統管理員身分執行</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">以系統管理員權限啟動選取的程式（支援可執行檔案、捷徑、批次處理腳本等）。</td></tr><tr><td style="text-align:left;"><strong>複製完整路徑</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">將檔案的絕對路徑（如 <code>D:\\Projects\\app.exe</code>）複製到剪貼簿。</td></tr><tr><td style="text-align:left;"><strong>剪下 / 複製檔案</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">將檔案本身放入剪貼簿，可直接在檔案總管或其他目錄中貼上。</td></tr><tr><td style="text-align:left;"><strong>貼上到此處</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">當選取目標為資料夾時，將剪貼簿中的檔案直接貼上至該目錄下。</td></tr><tr><td style="text-align:left;"><strong>刪除（移入資源回收筒）</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">將選取的檔案或資料夾安全移至 Windows 資源回收筒。</td></tr><tr><td style="text-align:left;"><strong>徹底刪除</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">永久刪除選取的檔案或資料夾（不可從資源回收筒還原，會快顯二次確認）。</td></tr><tr><td style="text-align:left;"><strong>開啟 Windows 右鍵選單</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">展開原生的 Windows 檔案總管完整快顯功能表（包含第三方軟體擴充和傳送到子選單）。</td></tr></tbody></table><h3 id="動作選單互動與即時篩選" tabindex="-1">動作選單互動與即時篩選 <a class="header-anchor" href="#動作選單互動與即時篩選" aria-label="Permalink to &quot;動作選單互動與即時篩選&quot;">​</a></h3><ul><li><strong>即輸即篩選</strong>：展開動作選單後，直接打字即可按動作名稱快速篩選（例如輸入 <code>copy</code> 即刻定位到所有複製相關操作）。</li><li><strong>層級導覽</strong>：在帶有子選單的項目（如「傳送到」或階層式動作）上按下 <code>→</code> 或 <code>Enter</code> 進入下一級；按 <code>←</code> 或在過濾詞為空時按 <code>Backspace</code> 返回上一級。</li><li><strong>退出選單</strong>：按下 <code>Escape</code> 退出動作選單並返回主搜尋結果列表。</li></ul><h2 id="_2-完整搜尋視窗的結果列表互動" tabindex="-1">2. 完整搜尋視窗的結果列表互動 <a class="header-anchor" href="#_2-完整搜尋視窗的結果列表互動" aria-label="Permalink to &quot;2. 完整搜尋視窗的結果列表互動&quot;">​</a></h2><p>主搜尋視窗（<code>Ctrl+F</code>）專為海量檔案管理與多維度瀏覽設計：</p><ul><li><strong>按兩下路徑欄定位</strong>：按兩下結果列表中的<strong>檔案名稱</strong>為直接開啟檔案；按兩下<strong>路徑</strong>欄則會自動開啟該檔案所在的父級資料夾。</li><li><strong>無限串流式結果載入</strong>：在搜尋大容量磁碟或數百萬項目時，結果會隨後台索引引擎的檢索即時串流式呈現在列表中，無需等待全盤掃描完畢即可隨時點擊或選取操作。</li><li><strong>鍵盤循環導覽</strong>：在結果第一行按 <code>↑</code> 可直接跳轉到末尾行，在最後一行按 <code>↓</code> 可回到首行。</li><li><strong>視窗無邊框拖曳與尺寸記憶</strong>：主視窗頂部非輸入區域可作為拖曳抓取條，滑鼠游標懸停時會有提示條淡入；手動調整的視窗寬高會自動記憶並在下次啟動時沿用。</li></ul><h2 id="_3-quicklook-即時預覽機制" tabindex="-1">3. QuickLook 即時預覽機制 <a class="header-anchor" href="#_3-quicklook-即時預覽機制" aria-label="Permalink to &quot;3. QuickLook 即時預覽機制&quot;">​</a></h2><p>在任意搜尋結果上按下 <code>Alt+P</code>，即可在搜尋視窗旁呼出一個功能強大的即時預覽面板，支援豐富的檔案類型：</p><h3 id="多格式預覽支援" tabindex="-1">多格式預覽支援 <a class="header-anchor" href="#多格式預覽支援" aria-label="Permalink to &quot;多格式預覽支援&quot;">​</a></h3><ul><li><strong>圖片與向量圖</strong>：支援 JPG、PNG、GIF（動圖自動播放）、BMP、WebP、ICO、SVG 等常見影像格式的高畫質縮放呈現。</li><li><strong>文件與文字代碼</strong>：支援 TXT、Markdown、JSON、XML、YAML、C#、Python、JS、HTML 等代碼與文字的高亮排版呈現。</li><li><strong>音訊/影片即時播放</strong>：MP4、MKV、AVI、MOV、WMV、MP3、WAV、FLAC、WMA 等媒體檔案在預覽面板開啟時會<strong>自動開始播放</strong>，並配備自適應主題的迷你控制條（播放/暫停、拖曳進度、即時長度、靜音控制），切換選取項目時立即停止。</li><li><strong>資料夾結構透視</strong>：選取資料夾時，預覽面板會自動列出其前 30 個直接子項目並顯示檔案圖示與大小，自動過濾系統和隱藏檔案。</li></ul><h3 id="細節設計與避讓機制" tabindex="-1">細節設計與避讓機制 <a class="header-anchor" href="#細節設計與避讓機制" aria-label="Permalink to &quot;細節設計與避讓機制&quot;">​</a></h3><ul><li><strong>尺寸與邊界自適應</strong>：預覽視窗的尺寸可在<a href="./settings/general.html#預覽"><strong>設定 → 一般 → 預覽視窗</strong></a>中自訂，系統會自動確保預覽視窗不會超出當前顯示器的可視工作區。</li><li><strong>原生彈窗自動避讓</strong>：當預覽 Office 加密文件彈出輸入密碼對話方塊時，Lertaro 會自動臨時隱藏快速視窗與預覽面板，待密碼輸入完成或彈窗關閉後自動無縫還原。</li><li><strong>預覽視窗拖曳源</strong>：預覽面板頂部可作為拖曳源，直接將正在預覽的檔案拖入編輯器、瀏覽器或外部通訊軟體中。</li></ul><h2 id="_4-外掛模組互動式與富文本預覽" tabindex="-1">4. 外掛模組互動式與富文本預覽 <a class="header-anchor" href="#_4-外掛模組互動式與富文本預覽" aria-label="Permalink to &quot;4. 外掛模組互動式與富文本預覽&quot;">​</a></h2><p>QuickLook 不僅支援本機檔案預覽，更開放了強大的外掛模組互動擴充能力：</p><ul><li><strong>自適應深淺色富文本</strong>：基於現代化 WebView2 與原生元件渲染，自動適配系統的深色/淺色主題，並注入清晰的高對比字型與精緻的半透明細捲軸。</li><li><strong>豐富的外掛模組卡片</strong>：支援詞典釋義卡片、即時天氣、網頁即時快照、API 偵錯資訊等複雜互動式面板。</li></ul><h2 id="_5-第三方獨立-quicklook-橋接-可選" tabindex="-1">5. 第三方獨立 QuickLook 橋接（可選） <a class="header-anchor" href="#_5-第三方獨立-quicklook-橋接-可選" aria-label="Permalink to &quot;5. 第三方獨立 QuickLook 橋接（可選）&quot;">​</a></h2><p>如果你已在系統中安裝了獨立的第三方開源工具 <strong>QuickLook</strong>（<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub 上的 QL-Win/QuickLook</a>），可以在<a href="./settings/plugins.html"><strong>設定 → 外掛模組</strong></a>中啟用內建的 <strong>QuickLook 橋接</strong> 外掛模組。</p><ul><li><strong>接管預覽</strong>：該外掛模組會透過本地具名管道連接獨立的 QuickLook 程序，並將外部預覽視窗自動吸附在 Lertaro 旁。</li><li><strong>無縫回退</strong>：若第三方 QuickLook 程序未運行或已關閉，Lertaro 會自動平滑回退至內建的原生預覽面板，確保預覽體驗始終可用。</li></ul>',23)])])}const f=e(a,[["render",n]]);export{u as __pageData,f as default};
